// OEM Network Function (use your IANA enterprise number)
constexpr ipmi::NetFn netFnOem = static_castipmi::NetFn>(0x30);

// OEM Commands
constexpr uint8_t cmdOemGetVersion = 0x01;
constexpr uint8_t cmdOemSetLed = 0x02;

// Handler: Get OEM Version
ipmi::RspTypeuint8_t, uint8_t, uint8_t>
    ipmiOemGetVersion()
{
    uint8_t major = 1;
    uint8_t minor = 0;
    uint8_t patch = 0;

    return ipmi::responseSuccess(major, minor, patch);
}

// Handler: Set LED state
ipmi::RspType ipmiOemSetLed(uint8_t ledId, uint8_t state)
{
    if (ledId > 3)
    {
        return ipmi::responseParmOutOfRange();
    }

    loglevel::INFO>("OEM Set LED",
        entry("LED=%d", ledId),
        entry("STATE=%d", state));

    // Implementation via D-Bus
    auto bus = sdbusplus::bus::new_default();
    auto method = bus.new_method_call(
        "xyz.openbmc_project.LED.GroupManager",
        "/xyz/openbmc_project/led/groups/identify",
        "org.freedesktop.DBus.Properties",
        "Set");

    method.append("xyz.openbmc_project.Led.Group", "Asserted");
    method.append(std::variantbool>(state == 1));

    try
    {
        bus.call(method);
    }
    catch (const std::exception& e)
    {
        return ipmi::responseUnspecifiedError();
    }

    return ipmi::responseSuccess();
}

// Register handlers
void registerOemHandlers()
{
    ipmi::registerHandler(
        ipmi::prioOemBase,
        netFnOem,
        cmdOemGetVersion,
        ipmi::Privilege::User,
        ipmiOemGetVersion);

    ipmi::registerHandler(
        ipmi::prioOemBase,
        netFnOem,
        cmdOemSetLed,
        ipmi::Privilege::Operator,
        ipmiOemSetLed);
}

